(function(root){'use strict';
const course='https://www.pandaaiquant.com/learninghub/newcourse';
const catalog=[
{id:'skill-trend',title:'上涨方向判断工具',kind:'AI 工具',concept:'换一段时间再测试',requires:[],status:'active',access:'local',fee:'示例',url:course,description:'帮助你判断上涨是不是还在继续，并提前写好什么时候退出。'},
{id:'strategy-value',title:'便宜股票检查工具',kind:'策略工具',concept:'从最高点跌了多少',requires:[],status:'active',access:'local',fee:'示例',url:course,description:'检查一只股票是真的便宜，还是公司本身出了问题。'},
{id:'strategy-defense',title:'少亏一点的资金管理工具',kind:'策略工具',concept:'钱投出去后还能剩多少',requires:[],status:'active',access:'local',fee:'示例',url:course,description:'帮助你限制一次最多投多少钱，并留一部分现金备用。'},
{id:'factor-research',title:'交易信号研究工具',kind:'研究工具',concept:'不能偷看未来消息',requires:[],status:'active',access:'local',fee:'示例',url:course,description:'检查一个买卖信号过去是否真的有用，而且不是碰巧挑中了好看的时间。'},
{id:'course-cost',title:'交易成本基础课',kind:'课程中心',concept:'交易成本',requires:[],status:'active',access:'local',fee:'公开入口',url:course,description:'区分毛收益、手续费和净收益，再开始第一个量化任务。'}];
const map={trend:'skill-trend',value:'strategy-value',defense:'strategy-defense',research:'factor-research'};
function knowledge(s){const a=s.knowledgeAttempts||[],answered=new Set(a.map(x=>x.id)).size,correct=new Set(a.filter(x=>x.correct).map(x=>x.id)).size,accuracy=answered?Math.round(correct/answered*100):0,level=answered<2?'知识水平待观察':correct>=4&&accuracy>=75?'研究型高手':correct>=2?'有经验投资者':'入门小白';return {level,answered,correct,accuracy,limitation:answered<2?'答题证据不足，暂不判断能力。':'只代表本游戏知识题，不代表真实投资能力。'};}
function validate(result,state){if(!['mock','ai'].includes(result.mode))throw Error('画像来源无效');const ids=new Set(state.evidence.map(e=>e.id));if(!Array.isArray(result.labels)||result.labels.length>12)throw Error('标签数量无效');for(const l of result.labels){if(!/^[a-z][a-z0-9_-]{0,39}$/.test(l.id)||!l.text||!l.context||!Array.isArray(l.evidence_ids)||!l.evidence_ids.length||l.evidence_ids.some(x=>!ids.has(x)))throw Error('画像缺少有效证据');}for(const r of result.recommendations)if(!catalog.some(c=>c.id===r.resource_id&&c.status==='active'))throw Error('推荐目录无效');return result;}
function analyze(s){const labels=[],groups={trend:[],value:[],defense:[],research:[]},meta={trend:['趋势型','趋势交易员'],value:['价值型','价值投资员'],defense:['防守型','风险管理师'],research:['研究型','量化研究员']};for(const e of s.evidence.filter(e=>e.dimension==='attribute'))if(groups[e.value])groups[e.value].push(e);for(const [id,ev] of Object.entries(groups))if(ev.length)labels.push({id:'type_'+id,text:meta[id][0]+'偏好 · '+meta[id][1],evidence_ids:ev.map(e=>e.id),context:'本局选择和建设共 '+ev.length+' 点；这是偏好，不是能力',status:s.analystCorrections?.['type_'+id]?.status||'candidate',edited:s.analystCorrections?.['type_'+id]?.text||null});const ranked=Object.entries(groups).sort((a,b)=>b[1].length-a[1].length),top=ranked[0],k=knowledge(s),recommendations=[];if(top[1].length)recommendations.push({resource_id:map[top[0]],reason:`你在 ${top[1].length} 次选择中最常走${meta[top[0]][0]}路线，下一步可以从一个简单任务开始。`,next_task:top[0]==='trend'?'选一个最近连续上涨的板块，写下什么时候买、跌到哪里退出':top[0]==='value'?'选一只跌了很多的股票，查清它是便宜了还是公司变差了':top[0]==='defense'?'先规定一次最多只能投入手里现金的多少':'挑一个买卖信号，换一段没看过的时间再测试'});recommendations.push({resource_id:k.level==='入门小白'||k.level==='知识水平待观察'?'course-cost':'factor-research',reason:k.level+'：'+(k.level.includes('待观察')?'先做几道基础题，再决定学什么。':'按你目前答题情况推荐下一步。'),next_task:k.level==='入门小白'||k.level==='知识水平待观察'?'算清一笔交易扣掉费用后真正赚了多少':'挑一个买卖信号，换一段时间再试一次'});return validate({mode:'mock',version:6,recommendedCareer:top[1].length?top[0]:null,knowledge:k,labels,narrative:top[1].length?`你最常走${meta[top[0]][0]}路线；推荐转职为${meta[top[0]][1]}。知识题结果是“${k.level}”。`:'还没有足够的策略选择。',recommendations},s);}
root.ProfileAnalyst={catalog,knowledge,validate,analyze};if(typeof module!=='undefined')module.exports=root.ProfileAnalyst;
})(typeof window==='undefined'?globalThis:window);
